    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.parameters = self.controller.Argument.parameters
        end)
    end))
    return coWait
end

function OverseaManageCookingListResultDialog:RefreshShow()
    if not isNull(self.parameters.localData) and not isNull(self.parameters.serverData) then
        local result = self.parameters.serverData.result
        local data = self.parameters.localData
        local makeNum = self.parameters.makeNum
        local recipeDojo = clone(maidCoffeePlayerComponent:GetRecipeDoJoById(data.refId))
        local recipeInfo = maidCoffeePlayerComponent:GetRecipeInfoByExp(data.refId,recipeDojo.exp)
        self.rewards = self.parameters.serverData.rewards
        self.oldRating = recipeDojo.rating
        local isCanLevelUp = self.parameters.serverData.rating > recipeDojo.rating
        self.isCanLevelUp = isCanLevelUp
        KTool.SetActive(self.NormalNode.gameObject,result == ResultType.Success)
        KTool.SetActive(self.SuccessNode.gameObject,result == ResultType.BigSuccess)
        KTool.SetActive(self.BigSuccessNode.gameObject,result == ResultType.BBigSuccess)
        if self.parameters.callBack then
            self.parameters.callBack(recipeInfo.isToMax)
        end
        KTool.SetActive(self.Success_NumberGlow2.gameObject,result == ResultType.BigSuccess)
        KTool.SetActive(self.BigSuccess_NumberGlow2.gameObject,result == ResultType.BBigSuccess)

        if recipeInfo.isToMax then
            KTool.SetActive(self.ImgSpecial.gameObject,result > ResultType.Success)
        else
            KTool.SetActive(self.ImproveImgSpecial.gameObject,result > ResultType.Success)
        end
        ---填充图片信息
        CfUtils.FillText(self.GoodsNum,makeNum)
        CfUtils.SetUISwitchImage(self.ImgBg,1)
        self:SetExpRoot()
        local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.foodId)
        if not isNull(foodVo) then
            CfUtils.FillImage(self.GoodsIcon.gameObject,foodVo.photoPath)
            CfUtils.FillText(self.GoodsName,foodVo.name)
        end

        local recipeVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.refId)
        if not isNull(recipeVo) then
            CfUtils.SetUISwitchImage(self.ImgLevel,self.parameters.serverData.rating)
            CfUtils.FillImage(self.ImgGoodsIcon.gameObject,recipeVo.photoPath)
        end
        if recipeInfo then
            KTool.SetActive(self.CooklistExp.gameObject,not recipeInfo.isToMax)
            if not recipeInfo.isToMax then
                local toRecipeInfo = maidCoffeePlayerComponent:GetRecipeInfoByExp(data.refId,self.parameters.serverData.exp)
                local addExp = checkNumber(self.parameters.serverData.exp) - checkNumber(recipeDojo.exp)
                CfUtils.FillText(self.AddExp, string.format("+%s",addExp))
                CfUtils.SetUISwitchText(self.AddExp,1)
                CfUtils.SetUISwitchText(self.TextDesc,1)
                local curValue = recipeInfo.leaveExp/recipeInfo.needExp
                self.Slider.value = curValue
                self.tweenCo = cs_coroutine.start(function()
                    coroutine.yield(Yielders.GetWaitForSeconds(1))
                    local toValue = toRecipeInfo.leaveExp/toRecipeInfo.needExp
                    if isCanLevelUp then
                        self.tween = CfUtils.DoTween(0.5,function(_value)
                            local value = curValue + ( 1 - curValue) * _value
                            self.Slider.value = value
                        end,function()
                            self.tween = CfUtils.DoTween(0.5,function(_value)
                                self.Slider.value = 0 + toValue * _value
                            end, function()
                                self.Slider.value = toValue
                            end)
                        end)
                    else
                        self.tween = CfUtils.DoTween(0.5,function(_value)
                            self.Slider.value = curValue + (toValue - curValue) * _value
                        end,function()
                            self.Slider.value = toValue
                        end)
                    end
                end)
                CfUtils.FillText(self.CurrentExpNum, string.format("%s/%s",toRecipeInfo.leaveExp,toRecipeInfo.needExp))
            end
        end
        if self.parameters.serverData.result == ResultType.BigSuccess or self.parameters.serverData.result == ResultType.BBigSuccess then
            local state = self.parameters.serverData.result == ResultType.BigSuccess and 1 or 2
            CfUtils.SetUISwitchImage(self.ImgSpecial,state)
            CfUtils.SetUISwitchImage(self.ImproveImgSpecial,state)
        end
        self.showCo = cs_coroutine.start(function()
            coroutine.yield(Yielders.GetWaitForSeconds(0.5))
            local bgState =  self.parameters.serverData.result == ResultType.Success and 1 or 2
            CfUtils.SetUISwitchImage(self.ImgBg,bgState)
            if recipeInfo.isToMax then
                coroutine.yield(Yielders.GetWaitForSeconds(0.1))
                CfUtils.FillText(self.GoodsNum, makeNum)
            end
            coroutine.yield(Yielders.GetWaitForSeconds(0.5))
            if recipeInfo and not recipeInfo.isToMax then
                local addExp = self.parameters.serverData.exp - recipeDojo.exp
                CfUtils.FillText(self.AddExp, string.format("+%s",addExp))
                local status = self.parameters.serverData.result == ResultType.Success and 1 or 2
                CfUtils.SetUISwitchText(self.AddExp,status)
                CfUtils.SetUISwitchText(self.TextDesc,status)
            end
        end)
    end
end

function OverseaManageCookingListResultDialog:SetExpRoot()
    local isHaveExp = false
    local num = 0
    for i, v in pairs(self.rewards) do
        if v.goodsId == ExpId then
            isHaveExp = true
            num = v.num
        end
    end
    CfUtils.SetActive(self.MessageGroup.gameObject, isHaveExp)
    if isHaveExp and num > 0 then
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(ExpId)
        if goodsVo then
            CfUtils.FillImage(self.ImgGoods,goodsVo.photoPath)
            CfUtils.FillText(self.TxtExp, string.format("%s+%s",goodsVo.name,num))
        end
    end
end

function OverseaManageCookingListResultDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            if not self.isDraw then
                if not isNull(self.rewards) and #self.rewards > 0 then
                    ---防止没有弹出领取奖励窗口  任务那边会有个顶上弹窗 直接跳过 OnBtnCloseClick 这一步骤
                    GoodsUtils.DrawRewards(self.rewards, true)
                end
            end
            self:RemoveCo()
            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end

function OverseaManageCookingListResultDialog:RemoveCo()

    if not isNull(self.showCo) then
        cs_coroutine.stop(self.showCo)
        self.showCo = nil
    end

    if not isNull(self.tweenCo) then
        cs_coroutine.stop(self.tweenCo)
        self.tweenCo = nil
    end

    if not isNull(self.tween) then
        self.tween:Kill()
        self.tween = nil
    end
end

function OverseaManageCookingListResultDialog:OnBtnCloseClick()
   -- if not self.isCanClick then return end
    if self.isCanLevelUp then
        --- 进入升级成功界面
        UIModule.OpenDialog({ id = Constants.UITypeIds.CultivateLevelUpSecondConfirmPanel, parameters = {
            levelUpType = Constants.UICultivateLevelUpFinishType.MaidCoffeeRecipeRatingUp,
            data = self.parameters.localData,
            oldRating = self.oldRating
        } })
        self.isCanLevelUp = false
    else
        local pRewards = self.rewards
        if not isNull(pRewards) and #pRewards > 0 then
            GoodsUtils.DrawRewards(pRewards, true)
            self.isDraw = true
            UIModule.BackDialog()
            --UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = pRewards } })
        end
        if self.parameters.closeCallBack then
            self.parameters.closeCallBack()
        end
    end
end

function OverseaManageCookingListResultDialog:__delete()
    self.controller = nil
    self.isCanClick = false
    self.oldRating = nil
end
return OverseaManageCookingListResultDialog